package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.config.ResultApplicationFactory;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;

/** Actual registration/day/analysis INPUT/worker/native result factory/content/body/entity/APPLIED chain. Transport is fictional. */
class CatalogDayAnalysisResultTest {
    boolean mysql(){return false;}
    CatalogDayAnalysisDispatchTest helper(){return new CatalogDayAnalysisDispatchTest(){@Override boolean mysql(){return CatalogDayAnalysisResultTest.this.mysql();}};}
    record Built(CatalogDayAnalysisDispatchTest helper,CatalogDayAnalysisDispatchTest.Built data,WorkerAuthorizationService.Identity identity,ResultApplicationFactory factory,AttemptOutcomeService.Application application,String raw){ }
    Built fixture(String category,boolean alias){var helper=helper();var data=helper.fixture(category,alias);var nativeData=data.data().data().data();var f=nativeData.f().f;var claim=data.worker().claim(helper.action("whole-result-claim"));assertEquals(WorkerAuthorizationService.State.CLAIMED,claim.state());assertEquals(WorkerAuthorizationService.State.SENT,data.worker().dispatch(claim.permit(),request->"fictional complete analysis response").state());
        var permissions=new HashMap<String,CatalogDayAnalysisResultPermitService>();for(String value:List.of("agent","skill","workflow","model"))permissions.put(value,value.equals(category)?new CatalogDayAnalysisResultPermitService(helper.helper().provider(data.data()),value):mock(CatalogDayAnalysisResultPermitService.class));
        var factory=new ResultApplicationFactory(f.source,f.tx,data.clock(),permissions);var application=factory.forAttempt(claim.permit().identity());var body=tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("title","Fictional complete entity analysis").put("category",category).put("entity_id",application.input().targetEntityId());body.putArray("sections");var refs=body.putArray("citation_ids");application.input().allowedCitationIds().stream().sorted().forEach(refs::add);var payload=tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("kind","analysis");payload.set("body",body);
        return new Built(helper,data,claim.permit().identity(),factory,application,ResultApplicationService.providerEnvelope(application.input(),JdbcFrozenInputs.canonical(payload)));
    }
    SharedWriteExecutor.ActionContext action(Built built,String name){return new SharedWriteExecutor.ActionContext("fictional-whole-analysis-result-"+name,built.identity().rootId(),built.identity().inputHash());}
    @Test void FourCategoriesApplyActualFullContentNativeVersionEntityStateAndPermanentReceipt(){for(String category:List.of("agent","skill","workflow","model")){var built=fixture(category,false);var data=built.data().data().data().data();var f=data.f().f;var result=built.application().service().applyAutomatic(built.application().input(),built.raw(),action(built,"apply"));assertEquals(ResultApplicationService.Status.APPLIED,result.status());assertEquals("analyzed",f.jdbc.queryForObject("SELECT analysis_state FROM analyzed_entities",String.class));assertEquals(1,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals("APPLIED",f.jdbc.queryForObject("SELECT application_state FROM jobs WHERE id=?",String.class,built.identity().rootId()));assertEquals("draft",f.jdbc.queryForObject("SELECT state FROM contents WHERE id=?",String.class,result.contentId()));assertEquals(built.identity().rootId(),f.jdbc.queryForObject("SELECT input_job_id FROM contents WHERE id=?",String.class,result.contentId()));var key=ContentVersionKey.fromJson(CanonicalJson.parse(f.jdbc.queryForObject("SELECT content_key_json FROM contents WHERE id=?",String.class,result.contentId())));assertEquals(built.identity().rootId(),key.inputJobId());assertEquals(result,resultOf(built,"apply"));assertEquals(2,f.sends);}}
    ResultApplicationService.Result resultOf(Built built,String name){return built.application().service().applyAutomatic(built.application().input(),built.raw(),action(built,name));}
    @Test void ActualAliasVersionTwoReplacesOnlyOriginalBaselineAndKeepsBothCitations(){var built=fixture("agent",true);var data=built.data().data().data().data();var f=data.f().f;var result=resultOf(built,"version");assertEquals(ResultApplicationService.Status.APPLIED,result.status());assertEquals("fictional-analysis",result.contentId());assertEquals(2L,result.contentRevision());assertEquals(2,f.jdbc.queryForObject("SELECT body_revision FROM contents WHERE id=?",Integer.class,result.contentId()));assertEquals(2,CanonicalJson.parse(f.jdbc.queryForObject("SELECT body_json FROM contents WHERE id=?",String.class,result.contentId())).get("citation_ids").size());assertEquals(2,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(CatalogPreviousAnalysisTest.Fixture.ROOT,f.jdbc.queryForObject("SELECT supersedes_job_id FROM jobs WHERE id=?",String.class,built.identity().rootId()));assertEquals(2,f.sends);}
    @Test void OriginalPermanentApplicationReceiptReplaysAfterAllCurrentBusinessTablesAreRemoved(){var built=fixture("model",false);var data=built.data().data().data().data();var f=data.f().f;var result=resultOf(built,"replay");for(String table:List.of("sources","source_run_items","analyzed_entities","contents"))f.jdbc.execute("DROP TABLE "+table);var original=built.factory().forAttempt(built.identity());assertEquals(result,original.service().applyAutomatic(original.input(),built.raw(),action(built,"replay")));assertEquals(2,f.sends);}
    @Test void NativeContentFailureRollsBackBodyEntityStateAppliedMarkerAndReceipt(){var built=fixture("workflow",false);var data=built.data().data().data().data();var f=data.f().f;f.jdbc.execute("ALTER TABLE contents ADD CONSTRAINT fictional_whole_analysis_write_failure CHECK(input_job_id<>'"+built.identity().rootId()+"')");assertThrows(RuntimeException.class,()->resultOf(built,"failure"));assertEquals("queued",f.jdbc.queryForObject("SELECT analysis_state FROM analyzed_entities",String.class));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM contents WHERE input_job_id=?",Integer.class,built.identity().rootId()));assertNull(f.jdbc.queryForObject("SELECT applied_at FROM jobs WHERE id=?",java.sql.Timestamp.class,built.identity().rootId()));assertEquals(1,f.jdbc.queryForObject("SELECT call_count FROM jobs WHERE id=?",Integer.class,built.identity().rootId()));assertEquals(2,f.sends);}
    @Test void ActualConfirmedManualReviewRevisionConflictUsesFreshCasAndSameOriginalProof(){var built=fixture("skill",true);var data=built.data().data().data().data();var f=data.f().f;f.jdbc.update("UPDATE contents SET revision=revision+1");var deferred=resultOf(built,"review-conflict");assertEquals(ResultApplicationService.Status.CONTENT_REVISION_CONFLICT,deferred.status());var manual=built.factory().forManual(built.identity(),new Actor("fictional-owner","owner"));long root=f.jdbc.queryForObject("SELECT revision FROM jobs WHERE id=?",Long.class,built.identity().rootId()),content=f.jdbc.queryForObject("SELECT revision FROM contents WHERE id='fictional-analysis'",Long.class);var key=action(built,"manual");var result=manual.service().applyManual(manual.input(),deferred.resultHash(),root,content,"Fictional owner confirms original result",true,key);assertEquals(ResultApplicationService.Status.APPLIED,result.status());assertEquals(content+1,result.contentRevision());assertEquals("analyzed",f.jdbc.queryForObject("SELECT analysis_state FROM analyzed_entities",String.class));assertEquals(result,manual.service().applyManual(manual.input(),deferred.resultHash(),root,content,"Fictional owner confirms original result",true,key));assertEquals(2,f.sends);}
    @Test void NewWholeProfileCannotApplyThroughDefaultFactoryWithoutActualNativePermissions(){var built=fixture("agent",false);var data=built.data().data().data().data();var f=data.f().f;var defaultFactory=new ResultApplicationFactory(f.source,f.tx,built.data().clock());var application=defaultFactory.forAttempt(built.identity());assertThrows(RuntimeException.class,()->application.service().applyAutomatic(application.input(),built.raw(),action(built,"missing-permission")));assertEquals("queued",f.jdbc.queryForObject("SELECT analysis_state FROM analyzed_entities",String.class));assertNull(f.jdbc.queryForObject("SELECT applied_at FROM jobs WHERE id=?",java.sql.Timestamp.class,built.identity().rootId()));assertEquals(2,f.sends);}
}
